  "zebra":["A zebra looks like a horse.","얼룩말은 말처럼 생겼어요.","'look like + 명사'는 ~처럼 보이다."],
  "wolf":["Wolves live in the forest.","늑대는 숲에 살아요.","wolf의 복수는 wolves(불규칙)."],
