  "camel":["A camel lives in the desert.","낙타는 사막에 살아요.","'in the desert'는 사막에서."],
  "kitten":["The kitten is so cute.","새끼고양이가 너무 귀여워요.","'so + 형용사'는 너무 ~한."],
