  "melon":["This melon smells sweet.","이 멜론은 달콤한 냄새가 나요.","'smell + 형용사'는 ~한 냄새가 나다."],
  "berry":["Birds eat berries.","새는 베리를 먹어요.","berry의 복수는 berries."],
